// Generated by scripts/attachment_admin_contract.py from the JSON schema of the
// agent service's attachment administration answers, which the host passes on
// unchanged; do not edit. Regenerate with
// `node scripts/attachment-admin-contract.mjs`; `--check` fails when it is stale.

/**
 * Why an attachment administration request was refused before any decision was
 * read.
 */
export type AttachmentAdminRefusalCode =
  "service_stopping" | "invalid_request" | "busy";

/**
 * What the approval card shows, from the agent's own record of the read and
 * the stored document.
 */
export type AttachmentCard = {
  kind: "card";
  name: string;
  media_type: string;
  size_bytes: number;
  provider: string;
  transport: string;
  model: string;
  action: ReleaseAction;
  existing_grant: boolean;
};

export type AttachmentCardAnswer =
  AttachmentCard | AttachmentNotRequired | AttachmentRefusal;

/**
 * The person's refusal of the read was recorded with the agent, which tells
 * the model.
 */
export type AttachmentDeclined = {
  kind: "declined";
};

/**
 * One remembered grant as the settings list shows it; never the bytes' digest
 * or conversation.
 */
export type AttachmentGrantEntry = {
  grant_id: string;
  action: ReleaseAction;
  lane: string;
  model: string;
  display_name: string | null;
};

/**
 * The remembered grants, in the order they were kept.
 */
export type AttachmentGrantList = {
  kind: "grants";
  grants: AttachmentGrantEntry[];
};

export type AttachmentGrantRevokeAnswer =
  AttachmentGrantRevoked | AttachmentRefusal;

/**
 * The grant is gone, and what it released that nothing has read was taken
 * back.
 */
export type AttachmentGrantRevoked = {
  kind: "revoked";
};

export type AttachmentGrantsAnswer = AttachmentGrantList | AttachmentRefusal;

/**
 * The read stays on this computer, so no decision of the person's is asked
 * for.
 */
export type AttachmentNotRequired = {
  kind: "not_required";
};

/**
 * A refused attachment request, by its closed code.
 *
 * Once the service has resolved the read it also names the file and the lane
 * the read would have gone to, so the window can say which file was not sent.
 */
export type AttachmentRefusal = {
  kind: "refused";
  code: DisclosureRefusalCode | AttachmentAdminRefusalCode;
  name: string | null;
  provider: string | null;
};

export type AttachmentReleaseAnswer =
  | AttachmentReleased
  | AttachmentDeclined
  | AttachmentNotRequired
  | AttachmentRefusal;

/**
 * The read was recorded and released to the agent.
 */
export type AttachmentReleased = {
  kind: "released";
};

/**
 * Why a read was refused, in the closed vocabulary the window words.
 */
export type DisclosureRefusalCode =
  | "acknowledgement_missing"
  | "reference_unknown"
  | "document_removed"
  | "gestor_mode"
  | "cloud_upload_not_permitted"
  | "profile_not_eligible"
  | "file_changed_during_read"
  | "not_signed_in"
  | "grant_revoked"
  | "service_failed";

export type ReleaseAction = "document_text" | "page_images";

/**
 * How far the person's approval reaches.
 */
export type ReleaseScope = "once" | "session" | "remember";
